ALTER TABLE organization ADD COLUMN IF NOT EXISTS unit_type VARCHAR(16) NULL;
CREATE TABLE IF NOT EXISTS hr_organization_head (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, person_id CHAR(36) NOT NULL, effective_from DATETIME NOT NULL, effective_until DATETIME NULL, created_at DATETIME NOT NULL, KEY hr_organization_head_active_index (organization_id, effective_until), KEY hr_organization_head_person_index (person_id, effective_until), CONSTRAINT hr_organization_head_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id), CONSTRAINT hr_organization_head_person_fk FOREIGN KEY (person_id) REFERENCES person(id));
